"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["48114"],{706(e){e.exports=JSON.parse('{"id":"V4-198","slug":"evergreen-fund","term":"Evergreen Fund","also_known_as":[],"difficulty":"Advanced","definition":"An evergreen fund is a private markets fund with no fixed end date, which accepts new money and allows investors to withdraw money periodically, rather than operating for a set period like a traditional closed-end fund.","explanation":["Traditional private equity and private credit funds typically have fixed lives of around ten years. Investors commit money at the start, the manager calls it over several years, and the fund returns money as investments are sold, then closes.","Evergreen funds work differently. Investors usually invest their money immediately, and the fund reinvests proceeds from sales rather than distributing them. Investors can buy into the fund at regular intervals, often monthly, and request withdrawals, often quarterly, subject to limits.","For example, an evergreen private equity fund might allow investors to withdraw up to 5% of the fund\u2019s value each quarter, with the manager able to limit withdrawals if requests exceed that amount.","Evergreen funds have become popular as a way to give wealthy individuals access to private markets, since they are simpler and require smaller minimum investments than traditional funds.","However, the underlying investments remain illiquid. If many investors ask for their money back at once, the fund may limit or suspend withdrawals, as happened with some large property funds. Investors also need to understand how the fund values its assets, since values are based on estimates."],"note":"","total":1725,"prev":{"slug":"event-driven-strategy","term":"Event-Driven Strategy"},"next":{"slug":"ex-dividend-date","term":"Ex-Dividend Date"}}')}}]);